/* Retro Arcade Theme — Tailwind v3 (hsl) */
/* Channel triplets — consume via hsl(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Retro Arcade Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 43.83 87.48% 93.28%;
    --foreground: 192.51 73.3% 14.85%;
    --card: 45.57 47.02% 87.96%;
    --card-foreground: 192.51 73.3% 14.85%;
    --popover: 45.57 47.02% 87.96%;
    --popover-foreground: 192.51 73.3% 14.85%;
    --primary: 331.09 62.83% 51.79%;
    --primary-foreground: 300 50% 100%;
    --secondary: 175.38 56.36% 40.01%;
    --secondary-foreground: 300 50% 100%;
    --muted: 180.07 8.76% 60.26%;
    --muted-foreground: 192.51 73.3% 14.85%;
    --accent: 17.2 77.25% 44.57%;
    --accent-foreground: 300 50% 100%;
    --destructive: 0.83 73.23% 52.74%;
    --destructive-foreground: 300 50% 100%;
    --border: 186.32 8.32% 54.64%;
    --input: 186.32 8.32% 54.64%;
    --ring: 331.09 62.83% 51.79%;
    --chart-1: 204.59 71.34% 47.77%;
    --chart-2: 175.38 56.36% 40.01%;
    --chart-3: 331.09 62.83% 51.79%;
    --chart-4: 17.2 77.25% 44.57%;
    --chart-5: 0.83 73.23% 52.74%;
    --radius: 0.25rem;
    --sidebar: 43.83 87.48% 93.28%;
    --sidebar-foreground: 192.51 73.3% 14.85%;
    --sidebar-primary: 331.09 62.83% 51.79%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 175.38 56.36% 40.01%;
    --sidebar-accent-foreground: 300 50% 100%;
    --sidebar-border: 186.32 8.32% 54.64%;
    --sidebar-ring: 331.09 62.83% 51.79%;
    --font-sans: Outfit, sans-serif;
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono: Space Mono, monospace;
    --shadow-color: 196 83% 10%;
    --shadow-opacity: 0.15;
    --shadow-blur: 4px;
    --shadow-spread: 0px;
    --shadow-offset-x: 2px;
    --shadow-offset-y: 2px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 2px 2px 4px 0px hsl(196 83% 10% / 0.07);
    --shadow-xs: 2px 2px 4px 0px hsl(196 83% 10% / 0.07);
    --shadow-sm:
      2px 2px 4px 0px hsl(196 83% 10% / 0.15),
      2px 1px 2px -1px hsl(196 83% 10% / 0.15);
    --shadow:
      2px 2px 4px 0px hsl(196 83% 10% / 0.15),
      2px 1px 2px -1px hsl(196 83% 10% / 0.15);
    --shadow-md:
      2px 2px 4px 0px hsl(196 83% 10% / 0.15),
      2px 2px 4px -1px hsl(196 83% 10% / 0.15);
    --shadow-lg:
      2px 2px 4px 0px hsl(196 83% 10% / 0.15),
      2px 4px 6px -1px hsl(196 83% 10% / 0.15);
    --shadow-xl:
      2px 2px 4px 0px hsl(196 83% 10% / 0.15),
      2px 8px 10px -1px hsl(196 83% 10% / 0.15);
    --shadow-2xl: 2px 2px 4px 0px hsl(196 83% 10% / 0.38);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 192.18 100% 10.75%;
    --foreground: 180.07 8.76% 60.26%;
    --card: 192.51 73.3% 14.85%;
    --card-foreground: 180.07 8.76% 60.26%;
    --popover: 192.51 73.3% 14.85%;
    --popover-foreground: 180.07 8.76% 60.26%;
    --primary: 331.09 62.83% 51.79%;
    --primary-foreground: 300 50% 100%;
    --secondary: 175.38 56.36% 40.01%;
    --secondary-foreground: 300 50% 100%;
    --muted: 194.45 15.19% 39.76%;
    --muted-foreground: 180.07 8.76% 60.26%;
    --accent: 17.2 77.25% 44.57%;
    --accent-foreground: 300 50% 100%;
    --destructive: 0.83 73.23% 52.74%;
    --destructive-foreground: 300 50% 100%;
    --border: 194.45 15.19% 39.76%;
    --input: 194.45 15.19% 39.76%;
    --ring: 331.09 62.83% 51.79%;
    --chart-1: 204.59 71.34% 47.77%;
    --chart-2: 175.38 56.36% 40.01%;
    --chart-3: 331.09 62.83% 51.79%;
    --chart-4: 17.2 77.25% 44.57%;
    --chart-5: 0.83 73.23% 52.74%;
    --radius: 0.25rem;
    --sidebar: 192.18 100% 10.75%;
    --sidebar-foreground: 180.07 8.76% 60.26%;
    --sidebar-primary: 331.09 62.83% 51.79%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 175.38 56.36% 40.01%;
    --sidebar-accent-foreground: 300 50% 100%;
    --sidebar-border: 194.45 15.19% 39.76%;
    --sidebar-ring: 331.09 62.83% 51.79%;
    --font-sans: Outfit, sans-serif;
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono: Space Mono, monospace;
    --shadow-color: 196 83% 10%;
    --shadow-opacity: 0.15;
    --shadow-blur: 4px;
    --shadow-spread: 0px;
    --shadow-offset-x: 2px;
    --shadow-offset-y: 2px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 2px 2px 4px 0px hsl(196 83% 10% / 0.07);
    --shadow-xs: 2px 2px 4px 0px hsl(196 83% 10% / 0.07);
    --shadow-sm:
      2px 2px 4px 0px hsl(196 83% 10% / 0.15),
      2px 1px 2px -1px hsl(196 83% 10% / 0.15);
    --shadow:
      2px 2px 4px 0px hsl(196 83% 10% / 0.15),
      2px 1px 2px -1px hsl(196 83% 10% / 0.15);
    --shadow-md:
      2px 2px 4px 0px hsl(196 83% 10% / 0.15),
      2px 2px 4px -1px hsl(196 83% 10% / 0.15);
    --shadow-lg:
      2px 2px 4px 0px hsl(196 83% 10% / 0.15),
      2px 4px 6px -1px hsl(196 83% 10% / 0.15);
    --shadow-xl:
      2px 2px 4px 0px hsl(196 83% 10% / 0.15),
      2px 8px 10px -1px hsl(196 83% 10% / 0.15);
    --shadow-2xl: 2px 2px 4px 0px hsl(196 83% 10% / 0.38);
  }

}
